import{_ as l,o as i,c as t,a2 as a}from"./chunks/framework.BXzK3EA4.js";const o="/assets/e3538ea4fc0781d1.DQJWHx9w.png",e="/assets/6c26fc50c8d9fd4c.DIGB1HG8.png",s="/assets/01928db44a84aecd.DjGpi58q.png",r="/assets/26bd9ac97f9ebdef.Dl09RkIp.png",C=JSON.parse('{"title":"Linux系统如何使用atop监控工具","description":"","frontmatter":{"title":"Linux系统如何使用atop监控工具"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/linux/how-to-use-atop.md","filePath":"ops-knowledge-base/operating-system/linux/how-to-use-atop.md","lastUpdated":1788259091000}'),n={name:"ops-knowledge-base/operating-system/linux/how-to-use-atop.md"};function c(u,p,_,P,d,m){return i(),t("div",null,[...p[0]||(p[0]=[a('<p>Atop是一款用于监控Linux系统资源与进程的工具，它以一定的频率记录系统的运行状态，所采集的数据包含系统CPU、内存、磁盘、网络的资源使用情况和进程运行情况，并能以日志文件的方式保存在磁盘中，服务器出现问题后，可获取相应的atop日志文件进行分析。</p><ul><li><p>CentOS系统执行如下命令安装:</p></li><li><p>yum -y install epel-release</p></li><li><p>yum install atop –y</p></li><li><p>Ubuntu系统执行如下命令安装:</p></li><li><p>apt-get install atop –y</p></li></ul><p>启动atop，执行如下命令:</p><ul><li>service atop start 或 systemctl start atop</li></ul><p><img src="'+o+'" alt=""></p><p>启动atop服务之后，执行如下命令，可以看到atop在后台运行，并且将数据写入指定目录。</p><ul><li>ps -ef | grep atop</li></ul><p><img src="'+e+'" alt=""></p><p>配置atop</p><p>/etc/sysconfig/atop：atop配置文件，主要用于调整atop监控周期，默认600s采集一次数据，如下图所示</p><p><img src="'+s+'" alt=""></p><p>/var/log/atop：用于存放atop监控日志文件的目录，atop在启动之后，会将采集记录存放在/var/log/atop目录，执行如下命令，查看日志文件。</p><ul><li>atop -r /var/log/atop/atop_20230311</li></ul><p>分析atop日志文件</p><p>atop常用指令如下所示：</p><ul><li><p>c：按照进程CPU使用率进行降序筛选。</p></li><li><p>m：按照进程内存使用率进行降序筛选。</p></li><li><p>d：按照进程磁盘使用率进行降序筛选。</p></li><li><p>a：按照进程资源综合使用率进行降序筛选。</p></li><li><p>n：按照进程网络使用率进行降序筛选，需要额外安装内核模块才支持，默认不支持。</p></li><li><p>t：跳转到下一个监控采集点。</p></li><li><p>T：跳转到上一个监控采集点。</p></li><li><p>B：指定时间点，格式为YYYYMMDDhhmm。</p></li></ul><p><img src="'+r+'" alt=""></p><p>系统资源监控字段含义</p><p>上图中列出了部分字段以及数值，每个字段的含义都是相对采样周期而言，各字段的含义如下所示：</p><ul><li><p>ATOP列：显示了主机名、信息采样日期和时间点。</p></li><li><p>PRC列：显示进程整体运行情况。</p></li><li><p>sys、user字段：分别代表进程在内核态和用户态的运行时间。</p></li><li><p>#proc字段：代表进程总数。</p></li><li><p>#zombie字段：代表僵死进程的数量。</p></li><li><p>#exit字段：代表atop采样周期期间退出的进程数量。</p></li><li><p>CPU列：显示CPU整体的使用情况，即多核CPU作为一个整体CPU资源的使用情况，我们知道CPU可被用于执行进程、处理中断，也可处于空闲状态，空闲状态分两种，一种是活动进程等待磁盘IO导致CPU空闲，另一种是完全空闲。</p></li><li><p>sys、user字段：CPU在用于处理进程时，进程在内核态、用户态所占CPU的时间比例。</p></li><li><p>irq字段：CPU用于处理中断的时间比例。</p></li><li><p>idle字段：CPU处在完全空闲状态的时间比例。</p></li><li><p>wait字段：CPU处在“进程等待磁盘IO导致CPU空闲”状态的时间比例。</p></li><li><p>cpu列：显示某一核CPU的使用情况，各字段含义可参照CPU列，各字段值相加结果为100%。</p></li><li><p>CPL列：显示CPU负载情况。</p></li><li><p>avg1、avg5和avg15字段：分别代表过去1分钟、5分钟和15分钟内运行队列中的平均进程数量。</p></li><li><p>csw字段：上下文切换次数。</p></li><li><p>intr字段：中断发生次数。</p></li><li><p>MEM列：代表内存的使用情况。</p></li><li><p>tot字段：物理内存总量。</p></li><li><p>free字段：空闲内存的大小。</p></li><li><p>cache字段：用于页缓存的内存大小。</p></li><li><p>buff字段：用于文件缓存的内存大小。</p></li><li><p>slab字段：系统内核占用的内存大小。</p></li><li><p>SWP列：显示交换空间的使用情况。</p></li><li><p>tot字段：交换区总量。</p></li><li><p>free字段：空闲交换空间大小。</p></li><li><p>PAG列：显示虚拟内存分页情况。</p></li><li><p>swin、swout字段：分别代表换入和换出内存页数。</p></li><li><p>DSK列：显示磁盘使用情况，每一个磁盘设备对应一列，如果有vdb设备，那么增多一列DSK信息。</p></li><li><p>vda字段：磁盘设备标识。</p></li><li><p>busy字段：磁盘忙时比例。</p></li><li><p>read、write字段：分别代表读、写请求数量。</p></li><li><p>NET列：多列NET展示了网络状况，包括传输层TCP和UDP、IP层以及各活动的网口信息。</p></li><li><p>XXXi字段：各层或活动网口收包数目。</p></li><li><p>XXXo字段：各层或活动网口发包数目。</p></li></ul>',20)])])}const U=l(n,[["render",c]]);export{C as __pageData,U as default};
